// Accessing the root document and modifying title dynamically:
console.log(document.nodeType); // 9 (DOCUMENT_NODE)
document.title = 'Updated Dashboard';

// HTML: <table><tr><td>Cell</td></tr></table>
// The DOM automatically inserts a <tbody> element:
const table = document.querySelector('table');
console.log(table.firstElementChild.tagName); // 'TBODY'

const div = document.createElement('div');
div.innerHTML = 'Hello <!-- comment --> World';

console.log(div.childNodes.length); // 3 (Text, Comment, Text nodes)
console.log(div.children.length);   // 0 (No Element children)

function inspectNode(node) {
  if (node.nodeType === Node.ELEMENT_NODE) {
    return `Element: <${node.tagName.toLowerCase()}>`;
  } else if (node.nodeType === Node.TEXT_NODE) {
    return `Text content: "${node.nodeValue.trim()}"`;
  }
  return `Other node type: ${node.nodeType}`;
}

document.addEventListener('readystatechange', () => {
  console.log('Current ready state:', document.readyState);
});

if (document.readyState === 'complete') {
  console.log('Page is already fully loaded.');
}

// Safe for DOM manipulation (fires first):
document.addEventListener('DOMContentLoaded', () => {
  console.log('DOM tree ready for interaction');
});

// Safe for calculating image dimensions (fires later):
window.addEventListener('load', () => {
  console.log('All images and styles fully loaded');
});
